func TestParseNetscape_SameSiteDefault(t *testing.T) {
	data := `example.com	TRUE	/	FALSE	2000000000	sess	val
`

	cookies, err := ParseNetscape(strings.NewReader(data), time.Date(2020, 1, 1, 0, 0, 0, 0, time.UTC))
	if err != nil {
		t.Fatalf("ParseNetscape failed: %v", err)
	}

	if len(cookies) != 1 {
		t.Fatalf("expected 1 cookie, got %d", len(cookies))
	}

	if cookies[0].SameSite != network.CookieSameSite("Lax") {
		t.Errorf("expected SameSite Lax, got %s", cookies[0].SameSite)
	}
}
